{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="Clinical, gentle aromatherapy practices and a membership model that may support calm, focus, and daily balance. Safety-forward guidance for home and group practice." />
  <link rel="stylesheet" href="assets/css/styles.css" />
</head>
<body class="page-home">
  <header class="site-header">
    <div class="wrap">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="main-nav" aria-label="Primary navigation">
        <ul>
          <li><a href="services.html">Practice</a></li>
          <li><a href="blends.html">Blends</a></li>
          <li><a href="shop.html">Boutique</a></li>
          <li><a href="pricing.html">Membership</a></li>
          <li><a href="about.html">About</a></li>
          <li><a href="book.html">Book</a></li>
          <li><a href="contact.html">Contact</a></li>
        </ul>
      </nav>
      <div class="actions">
        <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        <button id="try-now-btn" class="btn ghost" aria-haspopup="dialog">Try it now</button>
      </div>
    </div>
  </header>

  <main>
    <section class="hero" style="background-image: url('assets/img/pattern.svg');">
      <div class="wrap hero-inner reveal">
        <div class="hero-copy">
          <h1 class="hero-title">Thoughtful scent practices that may support day-to-day ease</h1>
          <p class="hero-lead">Personalized aroma-guided sessions and a membership for ongoing ritual. We focus on accessible practices and clear safety guidance so you can try aromatherapy with confidence.</p>
          <div class="hero-ctas">
            <a class="btn primary" href="book.html">Schedule a session</a>
            <button id="try-now-cta" class="btn ghost">Guided micro-practice</button>
          </div>
        </div>
        <div class="hero-card">
          <div class="card">
            <h3>Membership plan</h3>
            <p>Monthly access to curated blends, small-group practice, and home rituals that may support focus and rest.</p>
            <a class="btn small" href="pricing.html">Explore plans</a>
          </div>
        </div>
      </div>
    </section>

    <section class="story wrap reveal">
      <h2>Our approach</h2>
      <p>We center sensory practice, education, and safety. Sessions combine scent, breath, and short reflective prompts. Nothing we offer is medical — our language is careful: practices may support regulation, attention, and sleep when used responsibly.</p>
    </section>

    <section class="framework wrap reveal" id="framework">
      <h2>How sessions are structured</h2>
      <ol>
        <li><strong>Intake & safety:</strong> We review sensitivities, pregnancy/pets/dilution notes, and a patch-test approach.
        </li>
        <li><strong>Focus & intention:</strong> Set a small aim for the session — attention, unwind, or clarity.
        </li>
        <li><strong>Sensory practice:</strong> Guided smelling, brief breathwork, journaling prompts as desired.
        </li>
        <li><strong>Home guidance:</strong> Clear dilution and storage steps — practical, safety-forward notes for home use.
        </li>
      </ol>
    </section>

    <section class="offers wrap reveal">
      <h2>Programs & supports</h2>
      <div class="grid">
        <article class="offer">
          <h3>Solo session</h3>
          <p>60-minute one-on-one guidance, blend suggestions, and a short at-home plan. May support short-term focus, relaxation, or ritual development.</p>
          <a class="btn" href="book.html">Book solo</a>
        </article>
        <article class="offer">
          <h3>Small-group practice</h3>
          <p>Guided 45–60 minute gatherings for shared practice and learning. Limited group size to ensure individual attention.</p>
          <a class="btn" href="pricing.html">Join group</a>
        </article>
        <article class="offer">
          <h3>Monthly membership</h3>
          <p>Ongoing live practices, exclusive blends, and weekly micro-practices delivered via email. Practical safety resources included.</p>
          <a class="btn" href="pricing.html">View membership</a>
        </article>
      </div>
    </section>

    <section class="pricing-summary wrap reveal">
      <h2>Simple pricing</h2>
      <div class="cards">
        <div class="price-card">
          <h4>Intro session</h4>
          <p class="price">$85</p>
        </div>
        <div class="price-card">
          <h4>Drop-in group</h4>
          <p class="price">$25</p>
        </div>
        <div class="price-card">
          <h4>Membership</h4>
          <p class="price">$28 / month</p>
        </div>
      </div>
    </section>

    <section class="testimonials wrap reveal">
      <h2>What people say</h2>
      <blockquote>
        "Clear guidance, practical ingredients list, and short exercises I can repeat at home." — Community member
      </blockquote>
    </section>

    <section class="faq wrap reveal" id="faq">
      <h2>Common questions & safety notes</h2>
      <dl>
        <dt>Are these medical treatments?</dt>
        <dd>No — practices and blends are intended to be supportive and may support wellbeing. We do not make medical claims.
        </dd>
        <dt>How should I dilute essential oils?</dt>
        <dd>We provide dilution guidelines and recommend a patch test before regular topical use. Typical starting dilution is 0.5–2% depending on use case; specific ratios are provided per blend.
        </dd>
        <dt>What about pets and pregnancy?</dt>
        <dd>We include explicit guidance for pets and pregnancy in intake and blend notes. If you are pregnant or caring for animals, please mention this during intake so we can suggest safe alternatives.
        </dd>
      </dl>
    </section>

    <section class="cta wrap reveal">
      <h2>Ready to begin?</h2>
      <p>If you have questions, reach out — we’ll offer clear, safety-forward next steps.</p>
      <p class="cta-actions"><a class="btn primary" href="book.html">Book a consultation</a> <a class="btn ghost" href="contact.html">Contact us</a></p>
    </section>

  </main>

  <footer class="site-footer">
    <div class="wrap">
      <div class="footer-left">
        <strong>{{BUSINESS_NAME}}</strong>
        <p>{{CITY}}, {{STATE}}</p>
      </div>
      <div class="footer-right">
        <p>Call: <a href="tel:{{PHONE}}">{{PHONE}}</a></p>
        <p>Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
      </div>
    </div>
  </footer>

  <!-- Guided exercise modal (hidden) -->
  <div id="guided-modal" class="modal" role="dialog" aria-modal="true" aria-hidden="true">
    <div class="modal-panel" role="document">
      <header class="modal-header">
        <h3 id="modal-title">Guided micro-practice</h3>
        <button id="modal-close" class="modal-close" aria-label="Close">✕</button>
      </header>
      <main class="modal-body">
        <p class="muted">Choose a short exercise. These are non-medical practices which may support calm or attention.</p>
        <div class="exercise-tabs">
          <button class="ex-tab active" data-ex="breath">Breathing (2 min)</button>
          <button class="ex-tab" data-ex="journal">Journaling (3 min)</button>
          <button class="ex-tab" data-ex="intention">Intention (1 min)</button>
        </div>

        <section id="ex-breath" class="exercise ex-active">
          <div class="breath-ui">
            <div id="breath-circle" class="breath-circle" aria-hidden="true"></div>
            <p id="breath-instruction">Sit comfortably. Follow the circle.</p>
            <div class="breath-controls">
              <button id="breath-start" class="btn">Start</button>
              <button id="breath-stop" class="btn ghost">Stop</button>
            </div>
          </div>
        </section>

        <section id="ex-journal" class="exercise" hidden>
          <label for="journal-text">Prompt: Name three small things you notice right now.</label>
          <textarea id="journal-text" rows="6" placeholder="Write a few lines..." aria-label="Journaling text"></textarea>
          <div class="journal-actions">
            <button id="journal-save" class="btn">Save locally</button>
            <button id="journal-clear" class="btn ghost">Clear</button>
          </div>
          <p class="muted small">Entries are stored in your browser only.</p>
        </section>

        <section id="ex-intent" class="exercise" hidden>
          <p>Choose a short intention for the hour:</p>
          <div class="intent-grid">
            <button class="intent">Pause</button>
            <button class="intent">Focus</button>
            <button class="intent">Rest</button>
            <button class="intent">Clarity</button>
          </div>
          <div class="intent-actions">
            <button id="intent-set" class="btn">Set intention</button>
          </div>
        </section>
      </main>
    </div>
  </div>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
