{"path":"assets/css/styles.css","content":"/* Core design for aromatherapy site — no external assets */
:root{
  --bg:#f7f6f4; --card:#ffffff; --muted:#6b6b6b; --accent:#4a7c59; --accent-2:#7aa68a; --text:#1b1b1b; --radius:12px; --max:1100px;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial; color:var(--text); background:var(--bg); -webkit-font-smoothing:antialiased}
.wrap{max-width:var(--max);margin:0 auto;padding:2rem}
.site-header{background:linear-gradient(180deg, rgba(255,255,255,0.9), transparent);position:sticky;top:0;z-index:40;border-bottom:1px solid rgba(0,0,0,0.04)}
.site-header .wrap{display:flex;align-items:center;gap:1rem}
.brand{font-weight:700;color:var(--text);text-decoration:none}
.main-nav ul{list-style:none;margin:0;padding:0;display:flex;gap:1rem}
.main-nav a{color:var(--muted);text-decoration:none;padding:.5rem .25rem}
.actions{margin-left:auto;display:flex;gap:.5rem}
.btn{border:1px solid rgba(0,0,0,0.08);background:transparent;padding:.6rem .9rem;border-radius:8px;cursor:pointer}
.btn.primary{background:var(--accent);color:white;border:none}
.btn.ghost{background:transparent}
.btn.small{padding:.4rem .6rem;font-size:.9rem}
.hero{padding:3rem 0;background-color:var(--bg);background-image:none}
.hero-inner{display:grid;grid-template-columns:1fr 320px;gap:2rem;align-items:center}
.hero-card .card{background:var(--card);padding:1rem;border-radius:var(--radius);box-shadow:0 6px 18px rgba(23,23,23,0.06)}
.hero-title{font-size:clamp(1.5rem,2.5vw,2.25rem);margin:0 0 .5rem}
.hero-lead{color:var(--muted);margin:0 0 1rem}
.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:1rem}
.offer{background:var(--card);padding:1rem;border-radius:12px;box-shadow:0 6px 14px rgba(20,20,20,0.04)}
.price-card{background:var(--card);padding:1rem;border-radius:12px;text-align:center}
.price{font-weight:700;font-size:1.25rem;color:var(--accent)}
.testimonials blockquote{font-style:italic;color:var(--muted);border-left:4px solid var(--accent-2);padding-left:1rem}
footer.site-footer{border-top:1px solid rgba(0,0,0,0.05);padding:1.5rem 0;background:transparent}
.site-footer .wrap{display:flex;justify-content:space-between;align-items:center}
.muted{color:var(--muted)}
.small{font-size:.9rem}
/* Modal */
.modal{position:fixed;inset:0;display:flex;align-items:center;justify-content:center;padding:2rem;background:rgba(10,10,10,0.35);opacity:0;pointer-events:none;transition:opacity .18s ease}
.modal[aria-hidden="false"]{opacity:1;pointer-events:auto}
.modal-panel{background:var(--card);width:min(720px,94%);border-radius:12px;padding:1rem;box-shadow:0 12px 40px rgba(10,10,10,0.2)}
.modal-header{display:flex;justify-content:space-between;align-items:center}
.modal-close{background:transparent;border:none;font-size:1.25rem;cursor:pointer}
.exercise-tabs{display:flex;gap:.5rem;margin:.75rem 0}
.ex-tab{padding:.4rem .6rem;border-radius:8px;border:1px solid rgba(0,0,0,0.06);background:transparent;cursor:pointer}
.ex-tab.active{background:var(--accent);color:white}
.exercise{margin-top:1rem}
.breath-circle{width:160px;height:160px;margin:1rem auto;border-radius:50%;background:radial-gradient(circle at 40% 30%, rgba(122,166,138,.95), rgba(74,124,89,.95));display:block}
.breath-circle.pulse{animation:breath 4s ease-in-out infinite}
@keyframes breath{0%{transform:scale(1)}40%{transform:scale(1.25)}70%{transform:scale(1)}100%{transform:scale(1)}}
.breath-controls{display:flex;gap:.5rem;justify-content:center}
textarea{width:100%;padding:.6rem;border-radius:8px;border:1px solid rgba(0,0,0,0.08)}
.intent-grid{display:flex;gap:.5rem;flex-wrap:wrap}
.intent{padding:.5rem .7rem;border-radius:8px;border:1px solid rgba(0,0,0,0.08);background:transparent}
/* Reveal animations */
.reveal{opacity:0;transform:translateY(16px);transition:opacity .6s ease,transform .6s ease}
.reveal.in-view{opacity:1;transform:none}
/* prefers-reduced-motion */
@media (prefers-reduced-motion: reduce){
  .breath-circle.pulse{animation:none}
  .reveal{transition:none;opacity:1;transform:none}
}
/* Responsive */
@media (max-width:800px){
  .hero-inner{grid-template-columns:1fr}
  .actions{display:none}
  .main-nav ul{display:none}
}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Small DOM helpers
  function qs(sel, ctx) { return (ctx || document).querySelector(sel); }
  function qsa(sel, ctx) { return Array.from((ctx || document).querySelectorAll(sel)); }

  // Modal logic
  var modal = qs('#guided-modal');
  var modalClose = qs('#modal-close');
  var tryNowBtn = qs('#try-now-btn');
  var tryNowCta = qs('#try-now-cta');
  var tabs = qsa('.ex-tab');
  var exercises = qsa('.exercise');
  var breathCircle = qs('#breath-circle');
  var breathStart = qs('#breath-start');
  var breathStop = qs('#breath-stop');
  var journalText = qs('#journal-text');
  var journalSave = qs('#journal-save');
  var journalClear = qs('#journal-clear');
  var intentButtons = qsa('.intent');
  var intentSet = qs('#intent-set');
  var activeIntent = null;

  function openModal(){
    modal.setAttribute('aria-hidden','false');
    document.body.style.overflow = 'hidden';
    // ensure first tab visible
    activateTab(tabs[0]);
    qs('#modal-title').focus();
  }
  function closeModal(){
    modal.setAttribute('aria-hidden','true');
    document.body.style.overflow = '';
    stopBreathing();
  }

  tryNowBtn && tryNowBtn.addEventListener('click', openModal);
  tryNowCta && tryNowCta.addEventListener('click', openModal);
  modalClose.addEventListener('click', closeModal);
  modal.addEventListener('click', function(e){ if(e.target === modal) closeModal(); });
  document.addEventListener('keydown', function(e){ if(e.key === 'Escape') closeModal(); });

  // Tabs
  tabs.forEach(function(t){ t.addEventListener('click', function(){ activateTab(t); }); });
  function activateTab(button){
    tabs.forEach(function(b){ b.classList.remove('active'); });
    exercises.forEach(function(ex){ ex.hidden = true; ex.classList.remove('ex-active'); });
    button.classList.add('active');
    var key = button.getAttribute('data-ex');
    var el = qs('#ex-' + key);
    if(el){ el.hidden = false; el.classList.add('ex-active'); }
  }

  // Breathing exercise
  var breathTimer = null; var breathRunning = false; var breathPhase = 0; // 0 inhale,1 hold,2 exhale
  function startBreathing(){
    if(breathRunning) return;
    // Respect prefers-reduced-motion
    var reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    if(reduce){ qs('#breath-instruction').textContent = 'Follow slow breaths at a comfortable pace.'; breathCircle.classList.add('pulse'); breathRunning = true; return; }
    breathRunning = true;
    breathPhase = 0;
    breathCircle.classList.add('pulse');
    qs('#breath-instruction').textContent = 'Breathe: inhale for 4s, hold 2s, exhale 6s.';
    // simple cycle using intervals
    var cycle = function(){
      // loop indefinitely but update visual class (handled via CSS animation)
      breathPhase = (breathPhase + 1) % 3;
    };
    breathTimer = setInterval(cycle, 12000); // 12s per cycle
  }
  function stopBreathing(){
    if(breathTimer) { clearInterval(breathTimer); breathTimer = null; }
    breathCircle.classList.remove('pulse');
    breathRunning = false;
    qs('#breath-instruction').textContent = 'Sit comfortably. Follow the circle.';
  }
  breathStart.addEventListener('click', startBreathing);
  breathStop.addEventListener('click', stopBreathing);

  // Journaling storage
  var JOURNAL_KEY = 'aroma_journal_v1';
  journalSave.addEventListener('click', function(){
    var val = journalText.value || '';
    var entries = JSON.parse(localStorage.getItem(JOURNAL_KEY) || '[]');
    if(val.trim()){ entries.push({text:val, date: new Date().toISOString()}); localStorage.setItem(JOURNAL_KEY, JSON.stringify(entries)); journalText.value = ''; alert('Saved to your browser'); }
  });
  journalClear.addEventListener('click', function(){ if(confirm('Clear your current note?')) journalText.value = ''; });

  // Intent selection
  intentButtons.forEach(function(b){ b.addEventListener('click', function(){ intentButtons.forEach(function(x){ x.classList.remove('selected'); }); b.classList.add('selected'); activeIntent = b.textContent; }); });
  intentSet && intentSet.addEventListener('click', function(){ if(!activeIntent){ alert('Choose an intention'); return; } localStorage.setItem('aroma_intent', activeIntent); alert('Intent set: ' + activeIntent); });

  // Scroll reveal with IntersectionObserver and reduced-motion support
  var reveals = qsa('.reveal');
  var reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  if(!reduceMotion && 'IntersectionObserver' in window){
    var io = new IntersectionObserver(function(entries){
      entries.forEach(function(e){ if(e.isIntersecting){ e.target.classList.add('in-view'); io.unobserve(e.target); } });
    },{root:null,rootMargin:'0px 0px -10% 0px',threshold:0.09});
    reveals.forEach(function(r){ io.observe(r); });
  } else {
    // Respect reduced motion: reveal all immediately
    reveals.forEach(function(r){ r.classList.add('in-view'); });
  }

  // Accessibility: focus trap not implemented fully, keep simple focus management
})();"} 
